#include <lmcpp/lmcpp.hpp>
#include <cassert>
#include <sstream>
#include <fstream>
#include <unistd.h>
using namespace lmcpp;
static CliSpec spec(){CliSpec s{"t","1",{}};Operation o{"add",Access::Read,"", "object",{{"a",Type::Number,true},{"b",Type::Number,true}}};o.handler=[](const Params&p){return Json{{"value",p.at("a").get<int>()+p.at("b").get<int>()}};};s.operations.push_back(o);Operation en{"enum",Access::Read,"","object",{{"x",Type::String,true,nullptr,{"a","b"}}}};en.handler=[](const Params&p){return p;};s.operations.push_back(en);return s;}
int main(){auto s=spec();auto schema=publish_schema(s);assert(schema==publish_schema(s));assert(schema["schema"]=="cli.schema.v1");std::ostringstream out,err;assert(run_cli_io(s,{"add","--a","2","--b=3"},out,err)==0);assert(Json::parse(out.str())["value"]==5);out.str("");assert(run_cli_io(s,{"add","--input-json","{\"op\":\"add\",\"params\":{\"a\":2,\"b\":3}}"},out,err)==0);assert(Json::parse(out.str())["value"]==5);
  for(auto args:std::vector<std::vector<std::string>>{{"add","--wat","1"},{"add","--a","x","--b","2"},{"add","--a","1"},{"enum","--x","z"},{"add","--a","1","--a","2","--b","3"}}){out.str("");assert(run_cli_io(s,args,out,err)==2);auto e=Json::parse(out.str());assert(e["success"]==false);assert(!e["error"]["message"].get<std::string>().empty());}
  out.str("");assert(run_cli_io(s,{"--schema"},out,err)==0);assert(Json::parse(out.str())==schema);
  Operation boom{"boom",Access::Read,"","object",{}};boom.handler=[](const Params&)->Json{throw std::runtime_error("boom");};s.operations.push_back(boom);out.str("");assert(run_cli_io(s,{"boom"},out,err)==1);assert(Json::parse(out.str())["error"]["code"]=="INTERNAL_ERROR");
  std::string inp="/tmp/lmcpp-test-input.json";{std::ofstream f(inp);f<<"{\"a\":4,\"b\":6}";}out.str("");assert(run_cli_io(s,{"add","--input-file",inp},out,err)==0);assert(Json::parse(out.str())["value"]==10);::unlink(inp.c_str());
  Operation write{"note",Access::Write,"","object",{{"path",Type::String,true},{"text",Type::String,true}}};write.handler=[](const Params&p){std::ofstream f(p.at("path").get<std::string>(),std::ios::app);f<<p.at("text");return Json{{"written",true}};};s.operations.push_back(write);std::string note="/tmp/lmcpp-note-policy-test";::unlink(note.c_str());out.str("");assert(run_cli_io(s,{"note","--path",note,"--text","blocked","--readonly"},out,err)==6);assert(Json::parse(out.str())["error"]["code"]=="READONLY_VIOLATION");assert(::access(note.c_str(),F_OK)!=0);out.str("");assert(run_cli_io(s,{"note","--path",note,"--text","planned","--dryrun"},out,err)==0);assert(Json::parse(out.str())["dryRun"]==true);assert(::access(note.c_str(),F_OK)!=0);
  ::setenv("T_READONLY","true",1);out.str("");assert(run_cli_io(s,{"note","--path",note,"--text","blocked"},out,err)==6);::unsetenv("T_READONLY");::setenv("T_DRYRUN","yes",1);out.str("");assert(run_cli_io(s,{"note","--path",note,"--text","planned"},out,err)==0);::unsetenv("T_DRYRUN");assert(::access(note.c_str(),F_OK)!=0);
  Operation danger{"danger",Access::Write,"","object",{}};danger.dangerous=true;danger.handler=[](const Params&){return Json{{"done",true}};};s.operations.push_back(danger);out.str("");assert(run_cli_io(s,{"danger"},out,err)==9);out.str("");assert(run_cli_io(s,{"danger","--i-understand"},out,err)==0);
  std::string badfile="/tmp/lmcpp-bad-input.json";{std::ofstream f(badfile);f<<"{";}out.str("");assert(run_cli_io(s,{"add","--input-file",badfile},out,err)==3);assert(Json::parse(out.str())["error"]["code"]=="PARSE_ERROR");::unlink(badfile.c_str());out.str("");assert(run_cli_io(s,{"add","--input-file",badfile},out,err)==3);::unlink(note.c_str());
  std::string temp;{Context ctx;temp=ctx.temp_file_path();assert(::access(temp.c_str(),F_OK)==0);std::ofstream f(temp);f<<"{\"ok\":true}";f.close();assert(read_result_file(temp,"json")["ok"]==true);assert(read_result_file(temp,"text").is_object());}assert(::access(temp.c_str(),F_OK)!=0);
  std::string huge="/tmp/lmcpp-result-too-large";{std::ofstream f(huge,std::ios::binary);f.seekp(16*1024*1024);f.put('x');}bool capped=false;try{read_result_file(huge,"json");}catch(const Error&e){capped=e.code==ErrorCode::CommandFailed&&e.data["tool_code"]=="OUTPUT_TOO_LARGE";}assert(capped);::unlink(huge.c_str());
}
